using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Threading;using System.Windows.Forms;using System.Collections.Generic;
namespace GearLab {
 public static class Reducer55Tests {
  static int checks;static void Check(bool ok,string text){checks++;if(!ok)throw new Exception(text);}static void Wait(Func<bool> ready,string text,int seconds=180){var w=System.Diagnostics.Stopwatch.StartNew();while(!ready()&&w.Elapsed.TotalSeconds<seconds){Application.DoEvents();Thread.Sleep(20);}Check(ready(),text);}
  static IEnumerable<Control> All(Control root){yield return root;foreach(Control c in root.Controls)foreach(var d in All(c))yield return d;}
  public static int Run(string folder){Directory.CreateDirectory(folder);try{var reducers=new ReducerWorkspaceForm();using(var shell=new WorkspaceShell(reducers)){shell.Show();Application.DoEvents();Check(Application.OpenForms.Cast<Form>().Count(f=>f.TopLevel)==1,"single initial window");Check(shell.Pages.TabCount==1,"one reducer document");var nav=All(shell).OfType<ToolStrip>().SelectMany(c=>c.Items.Cast<ToolStripItem>()).Select(c=>c.Text).ToArray();Check(!nav.Contains("CAD")&&!nav.Contains("Полигоны")&&!nav.Contains("CAD Studio"),"CAD and polygons removed from visible navigation");for(int i=0;i<4;i++){reducers.TestSelect(i);Application.DoEvents();Check(shell.Pages.TabCount==1,"ordinary reducer uses same tab "+i);}reducers.SelectWave();Wait(()=>reducers.WaveView!=null&&reducers.WaveView.TestReady,"wave scheme available immediately");var wave=reducers.WaveView;Check(!wave.NativeReady&&!wave.IsBusy,"scheme does not wait for native build");using(var image=new Bitmap(wave.Diagram.Width,wave.Diagram.Height)){wave.Diagram.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(folder,"wave-scheme.png"));}Check(wave.Diagram.PaintedProfiles==2,"both gear contours drawn");Check(wave.Parameters.Flat&&wave.Parameters.FlexTeeth==100&&wave.Parameters.RingTeeth==102,"flat two-row layout");using(var image=new Bitmap(shell.Width,shell.Height)){shell.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(folder,"reducers-wave-ui.png"));}
    reducers.TestSelect(3);reducers.SelectWave();Check(ReferenceEquals(wave,reducers.WaveView)&&shell.Pages.TabCount==1,"wave returns to existing reducer workspace");shell.Navigate("wave");Check(shell.Pages.TabCount==1,"wave shortcut reuses main reducer tab");Check(Application.OpenForms.Cast<Form>().Count(f=>f.TopLevel)==1,"no popup windows from family switching");bool blocked=false;try{WorkspaceShell.Create("polygon");}catch(InvalidOperationException){blocked=true;}Check(blocked,"removed polygon entry blocked");
    foreach(int ratio in new[]{50,80,100}){var p=new WaveParameters{Ratio=ratio};p.Validate();Check(Math.Abs(p.OutputRpm+60.0/ratio)<1e-9,"output speed "+ratio);var q=WaveDiagram.Profile(p,false,Math.PI/2);Check(q.Length>100&&q.All(v=>!float.IsNaN(v.X)&&!float.IsNaN(v.Y)),"finite animated tooth profile "+ratio);WaveDiagram.Export(p,Path.Combine(folder,"Wave_"+ratio+".svg"),false);WaveDiagram.Export(p,Path.Combine(folder,"Wave_"+ratio+".dxf"),true);}
    var invalid=new WaveParameters{Module=double.NaN};blocked=false;try{invalid.Validate();}catch{blocked=true;}Check(blocked,"invalid dimensions rejected before sketch");
    wave.Build();Wait(()=>!wave.IsBusy,"flat native build finishes",300);Check(wave.NativeReady,"flat exact model built");wave.SaveNativePreview(Path.Combine(folder,"wave-flat-3d.png"));wave.Diagram.Phase=1;shell.ApproveTestClose();shell.Close();}
   File.WriteAllText(Path.Combine(folder,"reducer55-results.txt"),"PASS "+checks+" assertions: removed modeler navigation, one reducer workspace, immediate live scheme, correct ratios, SVG/DXF and flat native 3D.",Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"reducer55-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
